PREFIX brick: <https://brickschema.org/schema/Brick#>
PREFIX ref: <https://brickschema.org/schema/Brick/ref#>
SELECT ?p ?cls ?ts WHERE {
  ?s brick:isPointOf ?dev .
  ?s a ?cls .
  OPTIONAL { ?s ref:hasExternalReference ?r . ?r ref:hasTimeseriesId ?ts }
  BIND(strafter(str(?s), "#") AS ?p)
} ORDER BY ?p LIMIT 200

PREFIX brick: <https://brickschema.org/schema/Brick#>
PREFIX ref: <https://brickschema.org/schema/Brick/ref#>
SELECT ?p ?cls ?ts WHERE {
  ?s brick:isPointOf ?dev .
  ?s a ?cls .
  OPTIONAL { ?s ref:hasExternalReference ?r . ?r ref:hasTimeseriesId ?ts }
  FILTER( strafter(str(?s),"#") LIKE "VAV_F3_Z01%" || strafter(str(?s),"#") LIKE "Zone_F3_Z01%" )
  BIND(strafter(str(?s), "#") AS ?p)
} ORDER BY ?p

